            model += match_config[t, d] != t
        if where[t, d] == -1:
            model += match_config[t, d] != t

for d in days:
    for t1 in teams:
        for t2 in teams:
            if t1 != t2:
                model += cp.Implies(match_config[t1, d] == t2, match_config[t2, d] == t1)

for t in teams:
    for d in range(n_days - 2):
        model += cp.Implies(where[t, d] == -1, cp.Or(where[t, d+1] == 1, where[t, d+1] == 0))
        model += cp.Implies(where[t, d] == 1, cp.Or(where[t, d+1] == -1, where[t, d+1] == 0))

for t in teams:
    for d in range(n_days - 3):
        model += cp.Implies(where[t, d] == -1, cp.Or(where[t, d+1] == 1, where[t, d+1] == 0, where[t, d+2] == 1, where[t, d+2] == 0))
        model += cp.Implies(where[t, d] == 1, cp.Or(where[t, d+1] == -1, where[t, d+1] == 0, where[t, d+2] == -1, where[t, d+2] == 0))

for t in teams:
    model += cp.Sum([where[t, d] for d in range(n_days)]) == 0

for d in range(n_days):
    model += cp.Sum([where[t, d] for t in teams]) == 0

