    model += cp.Sum([where[t, d] for d in range(1, n_days, 2)]) == 4  # weekend home matches
    model += cp.Sum([where[t, d] for d in range(0, n_days, 2)]) == 4  # weekday home matches

for t in teams:
    for d in range(5):
        model += cp.Sum([where[t, d*2] for d in range(5)]) >= 2  # first weekends

for t in teams:
    if t in [1, 2]:  # Duke-UNC
        model += match_config[t, n_days-1] == 2 if t == 1 else match_config[t, n_days-1] == 1
    elif t in [0, 3]:  # Clem-GT
        model += match_config[t, n_days-1] == 3 if t == 0 else match_config[t, n_days-1] == 0
    elif t in [4, 7]:  # NCSt-Wake
        model += match_config[t, n_days-1] == 7 if t == 4 else match_config[t, n_days-1] == 4
    elif t in [5, 8]:  # UMD-UVA
        model += match_config[t, n_days-1] == 8 if t == 5 else match_config[t, n_days-1] == 5

for t in teams:
