        model += match_config[t, 11] == 1  # UNC plays Duke in date 11
        model += match_config[t, 1] == 0  # UNC plays Clem in date 2
    elif t == 1:  # Duke
        model += where[t, 15] == 0  # Duke has a bye in date 16
    elif t == 7:  # Wake
        model += where[t, 16] == -1  # Wake does not play home in date 17
        model += where[t, 0] == 0  # Wake has a bye in the first date

for t in teams:
    if t in [0, 1, 5, 7]:  # Clem, Duke, UMD, Wake
        model += where[t, n_days-1] != -1  # do not play away in the last date
    elif t in [0, 6, 3, 7]:  # Clem, FSU, GT, Wake
        model += where[t, 0] != -1  # do not play away in the first date
    elif t in [6, 4]:  # FSU, NCSt
        model += where[t, n_days-1] != 0  # do not have a bye in the last date

# Solve and print
if model.solve():
    solution = {'config': match_config.value().tolist(), 'where': where.value().tolist()}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
